const texto = prompt("Equipos");
const n = Number(texto);
if (texto.trim() === "" || !Number.isInteger(n) || n < 0 || n > 5) {
  console.log("Inscripción inválida");
} else {
  let total = 0;
  for (let i = 0; i < n; i = i + 1) { total = total + Number(prompt("Puntos")); }
  console.log("Puntos:", total);
}
